import { Composio } from '@composio/core';
import * as fs from 'fs';

async function main() {
    const composio = new Composio({ apiKey: process.env.COMPOSIO_API_KEY || "test" });
    const userId = "zealt-user01";

    console.log("Connecting to Composio for user:", userId);

    // 1. Lists the available trigger types for the `github` toolkit.
    const types = await composio.triggers.listTypes({ toolkits: ["github"] });
    console.log("Available github trigger types:", types.items.map(t => t.slug));

    const githubTrigger = types.items.find(t => t.slug === "GITHUB_ISSUE_EVENT" || t.slug.includes("ISSUE"));
    if (!githubTrigger) {
        throw new Error("Could not find GITHUB_ISSUE_EVENT or similar trigger type.");
    }
    console.log("Found trigger type:", githubTrigger.slug);

    // 2. Creates an active trigger for the GITHUB_ISSUE_EVENT
    const trigger = await composio.triggers.create(userId, githubTrigger.slug);
    console.log("Created trigger with ID:", trigger.triggerId);

    // 3. Disables the newly created trigger.
    const disabled = await composio.triggers.disable(trigger.triggerId);
    console.log("Disabled trigger:", disabled);

    // 4. Lists the active triggers for the user and verifies that the trigger is no longer active.
    let connectedAccountIds: string[] = [];
    try {
        const accounts = await composio.connectedAccounts.list({ userId });
        connectedAccountIds = accounts.items.map(a => a.id);
    } catch (e) {
        console.log("Could not list connected accounts, maybe user has none yet.", e);
    }

    let activeTriggers: any[] = [];
    if (connectedAccountIds.length > 0) {
        const active = await composio.triggers.listActive({ connectedAccountIds });
        activeTriggers = active.items;
    } else {
        // Just try listing all and filtering
        const active = await composio.triggers.listActive();
        // Since we don't have connectedAccountId, we might not be able to filter properly, but we can check the list
        activeTriggers = active.items;
    }

    console.log("Active triggers count:", activeTriggers.length);
    const isStillActive = activeTriggers.some(t => t.id === trigger.triggerId);
    console.log("Is trigger still active?", isStillActive);

    // 5. Saves the trigger details and its final status to `/home/user/trigger_status.json`.
    const statusData = {
        triggerId: trigger.triggerId,
        slug: githubTrigger.slug,
        disabledResult: disabled,
        isStillActive: isStillActive,
        finalStatus: "disabled"
    };

    fs.writeFileSync("/home/user/trigger_status.json", JSON.stringify(statusData, null, 2));
    console.log("Saved status to /home/user/trigger_status.json");
}

main().catch(console.error);
EOF
